// CRT: real Win32 wide-character conversion helpers for this project's
// own Bionic-shaped wchar_t (4 bytes, -fwchar-type=int) vs the genuine
// 2-byte UTF-16 code units every real Win32 wide-string API actually
// reads/writes. char16_t is portably guaranteed exactly 16 bits
// regardless of wchar_t's own width, so it is the real scratch-buffer
// type used at every actual OS call boundary this project's own
// filesystem patches touch (posix_compat.h, path.cpp, operations.cpp).
//
// Confirmed for real (2026-08-31): without this conversion, even a
// plain ASCII path corrupts completely -- e.g. GetTempPathW's own real
// output, read back through a 4-byte wchar_t*, truncates to a single
// garbled character (each 4-byte "unit" actually straddles two real
// 2-byte UTF-16 code units). See HISTORY.md's own entry for the full
// investigation and the live failure log this fix was verified against.
//
// Every element this project's own wchar_t path buffers ever hold is
// guaranteed to be a single valid UTF-16 code unit value (0x0000-
// 0xFFFF) by construction -- __char_to_wide() (path.cpp) is the only
// place raw narrow bytes ever enter this representation, and every
// other operation in this codebase (path parsing/concatenation/
// comparison) only ever copies or rearranges existing values, never
// invents a new one -- so a plain per-element narrow (truncate to the
// low 16 bits) or widen (zero-extend) conversion is exact and lossless
// in both directions.
#ifndef CRT_WIN32_WIDE_H
#define CRT_WIN32_WIDE_H

#include <cstddef>

namespace __crt_win32_wide {

// Narrows `len` elements of this project's own wchar_t buffer `src` into
// a genuine 2-byte scratch buffer `dst`, NUL-terminated -- for a real
// Win32 API's own *input* parameter. Caller owns `dst` (capacity >=
// len + 1).
inline void narrow(const wchar_t* src, size_t len, char16_t* dst) {
  size_t i;
  for (i = 0; i < len; ++i)
    dst[i] = static_cast<char16_t>(src[i]);
  dst[len] = 0;
}

// The reverse: widens `len` genuine 2-byte code units from `src` (what a
// real Win32 API actually wrote) into this project's own wchar_t buffer
// `dst` -- for a real Win32 API's own *output* parameter. Does not NUL-
// terminate (every real call site below already tracks its own real
// length separately and terminates its own destination buffer itself).
inline void widen(const char16_t* src, size_t len, wchar_t* dst) {
  size_t i;
  for (i = 0; i < len; ++i)
    dst[i] = static_cast<wchar_t>(src[i]);
}

} // namespace __crt_win32_wide

#endif // CRT_WIN32_WIDE_H

