// CRT: WideCharToMultiByte/MultiByteToWideChar are real Win32 wide-string
// APIs -- they read/write genuine 2-byte UTF-16 code units, not this
// project's own 4-byte wchar_t (-fwchar-type=int). Real char16_t scratch
// buffers are the actual OS call boundary; str's own wstring content
// (this project's own wchar_t) is narrowed into one before the call
// (__wide_to_char) or widened from one after it (__char_to_wide). See
// crt_win32_wide.h's own top comment for the full "why".
size_t __wide_to_char(const wstring& str, char* out, size_t outlen) {
  if (str.empty())
    return 0;
  ErrorHandler<size_t> err("__wide_to_char", nullptr);
  UINT codepage     = AreFileApisANSI() ? CP_ACP : CP_OEMCP;
  BOOL used_default = FALSE;
  std::unique_ptr<char16_t[]> real(new char16_t[str.size() + 1]);
  __crt_win32_wide::narrow(str.data(), str.size(), real.get());
  int ret = WideCharToMultiByte(
      codepage, 0, reinterpret_cast<const wchar_t*>(real.get()), str.size(), out, outlen, nullptr, &used_default);
  if (ret <= 0 || used_default)
    return err.report(errc::illegal_byte_sequence);
  return ret;
}

size_t __char_to_wide(const string& str, wchar_t* out, size_t outlen) {
  if (str.empty())
    return 0;
  ErrorHandler<size_t> err("__char_to_wide", nullptr);
  UINT codepage = AreFileApisANSI() ? CP_ACP : CP_OEMCP;
  // BUGFIX (found live via SIGSEGV, real crash on the very first non-
  // empty path concatenation): this function's own caller (include/
  // __filesystem/path.h) uses the standard MultiByteToWideChar
  // "measure first" idiom -- called once with out=nullptr/outlen=0 to
  // get the required size, then again with a real buffer. `real` must
  // stay null on the measure call (outlen==0), and widen() must only
  // ever write into `out` when the caller actually gave one -- the
  // first version of this fix unconditionally allocated `real` and
  // called widen(real.get(), ret, out), which on the measure call wrote
  // `ret` (the real, positive required size) wchar_t elements starting
  // at `out == nullptr`, a real null-pointer write crash.
  std::unique_ptr<char16_t[]> real(outlen != 0 ? new char16_t[outlen] : nullptr);
  int ret = MultiByteToWideChar(
      codepage, MB_ERR_INVALID_CHARS, str.data(), str.size(), reinterpret_cast<wchar_t*>(real.get()), outlen);
  if (ret <= 0)
    return err.report(errc::illegal_byte_sequence);
  if (out != nullptr)
    __crt_win32_wide::widen(real.get(), static_cast<size_t>(ret), out);
  return ret;
}

